// Preserve the current measured path; this adapter exports its existing definitions.
// preludes: form-stdlib/bml/formbin-codec.bml
section [form.bml] {
 let read = fbc-read-exact("observe/form-glass-frame-budget-run.fk",0);
 if not(fbc-good(read)) then form_error("complete frame-budget source required") else 0;
 let source = fbc-value(read);
 let marker = "    (let rows (fbr-frame 0 ";
 let at = str_find(source,marker,0);
 if le(at,0) then form_error("frame-budget definition boundary missing") else 0;
 let library = str_concat(substring(source,0,at),"    0)\n");
 if ne(write_file(".hearth/glass-stage-library.fk",library),str_len(library)) then form_error("complete private measurement library write") else 0;
 if ne(write_file(".hearth/glass-stage-held-source.fk",source),str_len(source)) then form_error("complete held measurement source write") else 0;
 if not(str_eq(read_file(".hearth/glass-stage-library.fk"),library)) then form_error("measurement library readback") else 0;
 print("private measurement definitions ready; no frames executed");
 1;
}

// One requested real sample. Timing rows are retained after the existing loop.
