   let rows = fbr-frame(0,list(),list(),list(),list(),list(),fgl-cache-empty(),list(),list());
   let finished = now_unix_ms();
   gbr-require(eq(len(rows),20),"one complete bounded twenty-frame observation");
   let summary = gbr-summary(rows);
