   let wire = json-emit-precise(report); let path = nsi-path(job,"report.json");
   gbr-require(eq(write_file(path,wire),str_len(wire)),"complete stage report write");
   gbr-require(str_eq(gbr-read(path),wire),"complete stage report readback");
   gbr-event(events,oh-applied(observed,selected,json-node-object(list(oh-n("frames_retained",len(rows)),oh-s("report",path)))));
   let fresh = oh-set(oh-reading("glass-frame-diagnostic",job,"frames-under-50ms",json-node-int(20),json-node-int(fbr-under(rows,0)),json-node-int(eq(fbr-under(rows,0),20)),list(),list("retain-evidence"),summary),"care_of",json-node-string(oh-str(observed,"id")));
   gbr-event(events,fresh);
   let accepted = oh-read(events);
   gbr-require(and(eq(len(accepted),1),str_eq(oh-str(head(accepted),"id"),oh-str(fresh,"id"))),"shared health reader accepted the correlated reobservation");
   gbr-require(and(str_eq(source,gbr-read("observe/form-glass-frame-budget-run.fk")),and(str_eq(old,gbr-read(".hearth/dsv4-closing-glass.log")),and(str_eq(prior,gbr-read(".hearth/dsv4-page-glass.log")),str_eq(priorErr,gbr-read(".hearth/dsv4-page-glass.err"))))),"measurement source and prior captures remained unchanged");
   print(list("bounded-glass-stage-reobservation",path,"events",events,"under-50ms",fbr-under(rows,0),"first",nth(head(reverse(rows)),6),"warm-max",fbr-col-max(fbr-warm(rows),6,0)));
   1;
  }
 }
 let request = read_line();
 if str_eq(request,"observe-20") then gbr-run() else 0;
}

