// Publish retained observations. No frame, model, GPU or learning execution.
// preludes: form-stdlib/bml/concept-source-audit.bml
section [form.bml] {
 class GlassStagePublication {
  def gsp-check(ok,message) = if ok then 1 else form_error(message);
  def gsp-state() = record_new(0,"root",".","hash","form-sha256","observations",0,"files",list());
