  def gsp-files(state,paths) = if nil?(paths) then list() else cons(gsp-content(state,head(paths)),gsp-files(state,tail(paths)));
  def gsp-current(state,paths) = if nil?(paths) then 1 else gsp-current-one(state,head(paths),tail(paths));
