  }
  def gsp-int(row,key) = node_value(oh-get(row,key));
  def gsp-frames(rows,index,under,maximum,warm) = if nil?(rows) then list(index,under,maximum,warm) else gsp-frame(head(rows),tail(rows),index,under,maximum,warm);
  def gsp-frame(row,rest,index,under,maximum,warm) {
   let total = gsp-int(row,"total_ms");
   let stages = add(gsp-int(row,"inventory_samples_ms"),add(gsp-int(row,"sensors_ms"),add(gsp-int(row,"heat_fast_kernel_ms"),add(gsp-int(row,"metrics_observations_ms"),gsp-int(row,"flow_render_ms")))));
   gsp-check(and(eq(gsp-int(row,"frame"),index),eq(stages,total)),"complete ascending frames and exact measured stage totals");
   gsp-frames(rest,add(index,1),add(under,if lt(total,50) then 1 else 0),if gt(total,maximum) then total else maximum,if and(gt(index,0),gt(total,warm)) then total else warm);
  }
  def gsp-events(lines) = if nil?(lines) then list() else if str_eq(head(lines),"") then gsp-events(tail(lines)) else cons(parse-json("retained-glass-health",head(lines)),gsp-events(tail(lines)));
  def gsp-event-text(rows) = if nil?(rows) then "" else str_concat(json-emit-precise(head(rows)),str_concat("\n",gsp-event-text(tail(rows))));
  def gsp-prior(state,base,context,under,first,warm) = json-node-object(list(oh-s("context",context),oh-n("under_50ms",under),oh-n("first_frame_ms",first),oh-n("warm_maximum_ms",warm),json-node-pair("stdout",gsp-content(state,str_concat(base,".log"))),json-node-pair("stderr",gsp-content(state,str_concat(base,".err"))),json-node-pair("execution_source_identities",json-node-null()),oh-s("identity_scope","These hashes identify the exact retained stream bytes. A per-execution source/runtime identity manifest was not retained with this sample; current source identities are not assigned to it.")));
  def gsp-run() {
   let state = gsp-state(); let base = ".hearth/source-inventory-30054-67380702-0";
   let reportPath = str_concat(base,"/report.json"); let eventsPath = str_concat(base,"/events.jsonl");
   let text = csa-file(state,reportPath); let report = parse-json(reportPath,text);
   gsp-check(str_eq(json-emit-precise(report),text),"complete report retains exact canonical bytes");
   let rows = json-array-elements(oh-get(report,"frames")); let stats = gsp-frames(rows,0,0,0,0);
   gsp-check(and(eq(head(stats),20),and(eq(nth(stats,1),19),and(eq(nth(stats,2),119),eq(nth(stats,3),45)))),"retained 20-frame target remains unmet with exact first and warm maxima");
   let events = gsp-events(split-on(csa-file(state,eventsPath),"\n"));
   gsp-check(and(eq(len(events),4),str_eq(gsp-event-text(events),csa-file(state,eventsPath))),"four complete exact health events");
   let reading = head(events); let response = nth(events,1); let applied = nth(events,2); let fresh = nth(events,3);
   gsp-check(and(oh-valid(reading),and(oh-valid(response),and(oh-valid(applied),oh-valid(fresh)))),"retained complete health shapes");
   gsp-check(and(str_eq(oh-str(reading,"stage"),"observe"),and(str_eq(oh-select(reading,response,"refuse"),"retain-stage-reobservation"),and(str_eq(oh-str(applied,"stage"),"applied"),and(str_eq(oh-str(reading,"id"),oh-str(applied,"id")),str_eq(oh-str(applied,"selected"),"retain-stage-reobservation"))))),"observation response and applied action remain correlated");
   gsp-check(and(str_eq(oh-str(fresh,"stage"),"observe"),and(str_eq(oh-str(fresh,"care_of"),oh-str(reading,"id")),and(eq(gsp-int(fresh,"observed"),19),eq(gsp-int(fresh,"health"),0)))),"fresh observation preserves unmet target and original care identity");
   let source = csa-file(state,".hearth/glass-stage-held-source.fk"); let at = str_find(source,"    (let rows (fbr-frame 0 ",0);
   gsp-check(and(gt(at,0),str_eq(str_concat(substring(source,0,at),"    0)\n"),csa-file(state,".hearth/glass-stage-library.fk"))),"private adapter exports unchanged public measurement definitions");
   gsp-check(str_eq(source,csa-file(state,"observe/form-glass-frame-budget-run.fk")),"held measurement source is still byte-identical to the public authority");
   let log = csa-file(state,".hearth/glass-stage-reobserve.log"); let err = csa-file(state,".hearth/glass-stage-reobserve.err");
   let ending = "@form fkwu 0 11584 0 11584\n";
   gsp-check(and(eq(str_len(err),0),and(eq(str_len(log),add(11584,str_len(ending))),str_eq(substring(log,11584,str_len(log)),ending))),"actual retained execution envelope and full stdout extent agree");
   let priors = list(gsp-prior(state,".hearth/dsv4-closing-glass","Earlier runtime closing sample; retained aggregate only",19,65,18),gsp-prior(state,".hearth/dsv4-page-glass","Rebuilt runtime during concurrent CLI generation and proof work; retained aggregate only",12,229,68));
   let sources = gsp-files(state,list(".hearth/glass-stage-prepare.bml",".hearth/glass-stage-library.fk",".hearth/glass-stage-reobserve.bml",".hearth/glass-stage-held-source.fk"));
   let result = json-node-object(list(oh-s("schema","glass-stage-observation-evidence-v1"),oh-s("scope","One retained bounded diagnostic, without reexecution; no causal attribution or universal 50 ms performance claim"),oh-n("target_met",0),json-node-pair("report_identity",gsp-id(state,reportPath)),json-node-pair("report",report),json-node-pair("event_identity",gsp-id(state,eventsPath)),json-node-pair("events",json-node-array(events)),json-node-pair("adapter_sources",json-node-array(sources)),json-node-pair("public_measurement_authority",gsp-id(state,"observe/form-glass-frame-budget-run.fk")),oh-s("source_identity_scope","Adapter files are the unchanged retained measurement implementation. Hashes are recorded at publication; exact held public measurement definitions were compared before and after the sample. No complete historical transitive dependency or executable identity is inferred for any sample."),json-node-pair("prior_samples",json-node-array(priors)),json-node-pair("execution",json-node-object(list(oh-n("exit",0),oh-n("stdout_bytes",11584),oh-n("stderr_bytes",0),json-node-pair("stdout_capture",gsp-id(state,".hearth/glass-stage-reobserve.log")),json-node-pair("stderr_capture",gsp-id(state,".hearth/glass-stage-reobserve.err")),oh-s("status_basis","Exact retained form-run completion envelope checked against the complete stdout extent")))),json-node-pair("publisher",gsp-content(state,".hearth/glass-stage-publish.bml"))));
   let wire = json-emit-precise(result);
   gsp-current(state,record_get(state,"files"));
   let path = "docs/evidence/fkwu/glass-stage-observation.json";
   gsp-check(eq(write_file(path,wire),str_len(wire)),"complete public Glass evidence write");
   let readback = fbc-read-exact(path,0);
   gsp-check(and(fbc-good(readback),str_eq(fbc-value(readback),wire)),"exact complete public Glass evidence readback");
   print(list("published-retained-glass-evidence",path,"bytes",str_len(wire),"frames",20,"events",4,"target-met",0));
   1;
  }
 }
 let request = read_line();
 if str_eq(request,"publish-held") then gsp-run() else 0;
}
